<script>
(function(window,document){
'use strict';
var API='api/client-hub-settings.php';
var csrf=<?= json_encode($csrfToken, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
var state={settings:{},request_forms:[],booking_forms:[],can_update:false};
function E(id){return document.getElementById(id)}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}
function toast(t,m){if(typeof window.fieldplxToast==='function')window.fieldplxToast(t,m);else if(t==='error')window.alert(m)}
function icons(){if(window.lucide&&typeof window.lucide.createIcons==='function')window.lucide.createIcons()}
function fd(action){var f=new FormData();f.append('csrf_token',csrf);f.append('action',action);return f}
function request(data){return fetch(API,{method:'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(txt){var d;try{d=JSON.parse(txt)}catch(e){throw new Error('Invalid response from Customer Hub API.')}if(!r.ok||!d.success)throw new Error(d.message||'Request failed.');return d})})}
function checked(v){return Number(v||0)===1?' checked':''}
function optionList(list,current,noneLabel){var html='<option value="0">'+esc(noneLabel||'None')+'</option>';list.forEach(function(x){html+='<option value="'+Number(x.id)+'"'+(Number(x.id)===Number(current)?' selected':'')+'>'+esc(x.title||x.name||('Form '+x.id))+'</option>'});return html}
function portalMenu(){var show=Number(state.settings.quotes_invoices_visible||0)===1;var h='<div class="ch-preview"><div class="ch-preview-title">Preview</div><div class="ch-portal-preview"><div class="ch-new-request"><i data-lucide="plus"></i>New Request</div><div class="ch-preview-menu"><div class="ch-preview-item active"><i data-lucide="inbox"></i>Requests</div>';if(show){h+='<div class="ch-preview-item"><i data-lucide="badge-dollar-sign"></i>Quotes</div>'}h+='<div class="ch-preview-item"><i data-lucide="calendar-days"></i>Appointments</div>';if(show){h+='<div class="ch-preview-item"><i data-lucide="receipt-text"></i>Invoices</div>'}h+='<div class="ch-preview-rule"></div><div class="ch-preview-item"><i data-lucide="phone"></i>Contact Us</div><div class="ch-preview-item"><i data-lucide="log-out"></i>Log Out</div></div></div></div>';return h}
function signaturePreview(){var required=Number(state.settings.require_quote_signature||0)===1;var h='<div class="ch-preview"><div class="ch-preview-title">Preview</div><div class="ch-preview-card"><div class="ch-preview-card-head"><span>Approve Quote</span><i data-lucide="x"></i></div>';if(required){h+='<div class="ch-signature-body"><div class="ch-signature-tabs"><span>Draw</span><span>Type</span></div><div class="ch-signature-box"><div class="ch-signature-line">Write signature</div></div><p class="ch-preview-note">By writing your signature, you accept this quote, associated costs, and applicable terms.</p><div class="ch-preview-actions"><button class="ch-mini-btn" type="button">Cancel</button><button class="ch-mini-btn primary" type="button">Approve</button></div></div>'}else{h+='<div class="ch-signature-body"><div class="ch-thankyou"><i data-lucide="thumbs-up"></i><strong>Thank you for your business</strong></div><p class="ch-preview-note" style="text-align:center">By clicking Approve, you accept this quote, associated costs and applicable terms.</p><div class="ch-preview-actions"><button class="ch-mini-btn" type="button">Cancel</button><button class="ch-mini-btn primary" type="button">Approve</button></div></div>'}return h+'</div></div>'}
function changesPreview(){var enabled=Number(state.settings.allow_quote_change_requests||0)===1;var h='<div class="ch-preview"><div class="ch-preview-title">Preview</div><div class="ch-preview-card"><div class="ch-quote-preview"><div class="ch-quote-line"><span>Subtotal</span><strong>$30.00</strong></div><div class="ch-quote-line"><span>Tax (4.0%)</span><strong>$1.20</strong></div><div class="ch-quote-line"><span>Total</span><strong>$31.20</strong></div><div class="ch-quote-message">This quote is valid for the next 30 days, after which values may be subject to change.</div><div class="ch-quote-actions">';if(enabled)h+='<button class="ch-mini-btn" type="button">Request Changes</button>';h+='<button class="ch-mini-btn primary" type="button" style="'+(enabled?'':'grid-column:1/-1')+'">Approve</button></div></div></div></div>';return h}
function appointmentPreview(){var show=Number(state.settings.show_scheduled_time||0)===1;var h='<div class="ch-preview"><div class="ch-preview-title">Preview</div><div class="ch-preview-card"><div class="ch-appointment-preview"><div class="ch-appt-date">Tuesday, Jun 18, 2019</div>';if(show)h+='<div class="ch-appt-line"><i data-lucide="clock-3"></i><span>2:00 PM</span></div>';h+='<div class="ch-appt-line"><i data-lucide="map-pin"></i><span>289 NW 198th St<br>Shoreline, WA 98177</span></div></div></div></div>';return h}
function render(){var s=state.settings;var html='';
html+='<section class="ch-card"><div class="ch-card-head"><h2>Settings</h2></div><div class="ch-section"><div class="ch-section-title">Menu visibility</div><div class="ch-grid"><div><div class="ch-setting-row"><label class="ch-toggle"><input id="quotesInvoicesVisible" type="checkbox"'+checked(s.quotes_invoices_visible)+'><span class="ch-toggle-ui"></span></label><div class="ch-copy"><h3>Quotes and invoices</h3><p>Allow customers to navigate to and see a list of all sent quotes and invoices.</p></div></div></div><div id="portalPreview">'+portalMenu()+'</div></div></div>';
html+='<div class="ch-section"><div class="ch-section-title">Quote approval</div><div class="ch-grid"><div><div class="ch-setting-row"><label class="ch-toggle"><input id="requireQuoteSignature" type="checkbox"'+checked(s.require_quote_signature)+'><span class="ch-toggle-ui"></span></label><div class="ch-copy"><h3>Require customer signatures</h3><p>Require a signature when approving a quote.</p></div></div></div><div id="signaturePreview">'+signaturePreview()+'</div></div><div class="ch-grid" style="margin-top:34px"><div><div class="ch-setting-row"><label class="ch-toggle"><input id="allowQuoteChanges" type="checkbox"'+checked(s.allow_quote_change_requests)+'><span class="ch-toggle-ui"></span></label><div class="ch-copy"><h3>Customers can request changes</h3><p>Allow customers to request changes on a sent quote.</p></div></div></div><div id="changesPreview">'+changesPreview()+'</div></div></div>';
html+='<div class="ch-section"><div class="ch-section-title">Appointments</div><div class="ch-grid"><div><div class="ch-setting-row"><label class="ch-toggle"><input id="showScheduledTime" type="checkbox"'+checked(s.show_scheduled_time)+'><span class="ch-toggle-ui"></span></label><div class="ch-copy"><h3>Show scheduled time</h3><p>Allow customers to see the scheduled time for assessments and visits.</p></div></div></div><div id="appointmentPreview">'+appointmentPreview()+'</div></div></div></section>';
html+='<section class="ch-form-card"><h2>Request and booking forms</h2><p>Choose which forms customers can access and submit from Customer Hub. This controls what information you collect and how customers get in touch.</p><div class="ch-field"><label>Request form</label><select class="ch-select" id="requestForm">'+optionList(state.request_forms,s.request_form_page_id,'None')+'</select></div><div class="ch-field"><label>Booking form</label><select class="ch-select" id="bookingForm">'+optionList(state.booking_forms,s.booking_form_page_id,'None')+'</select></div><div class="ch-radio-title">Choose the primary button shown in Customer Hub</div><label class="ch-radio"><input type="radio" name="primaryAction" value="request"'+(String(s.primary_action||'request')==='request'?' checked':'')+'><span>Requests<small>Customers see a button to send a service request</small></span></label><label class="ch-radio"><input type="radio" name="primaryAction" value="booking"'+(String(s.primary_action)==='booking'?' checked':'')+'><span>Bookings<small>Customers see a button to book an appointment</small></span></label></section>';
html+='<section class="ch-form-card"><h2>Referral settings</h2><div class="ch-referral-row"><div><div class="ch-copy"><h3>Customers can refer a friend</h3><p>Show a referral option in Customer Hub so customers can share your business with friends by text, email, or social media.</p></div><div style="margin-top:12px"><div class="ch-copy"><h3>Templates</h3><p>Customize the message customers share with friends.</p></div></div></div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:44px"><label class="ch-toggle"><input id="referralsEnabled" type="checkbox"'+checked(s.referrals_enabled)+'><span class="ch-toggle-ui"></span></label><button type="button" class="ch-link" id="editReferralMessage">Edit</button></div></div></section>';
html+='<section class="ch-form-card"><h2>Share login page</h2><p>Allow existing customers to log in to Customer Hub by adding the following URL to your website.</p><div class="ch-login-row"><button type="button" class="ch-copy-btn" id="copyLoginUrl">Copy URL</button><input class="ch-input ch-login-url" id="shareLoginUrl" readonly value="'+esc(s.share_url||'')+'"></div></section>';
html+='<div class="ch-save-row"><button type="button" class="ch-btn primary" id="updateClientHub">Update Settings</button></div>';
E('clientHubRoot').innerHTML=html;wire();icons()}
function wire(){E('quotesInvoicesVisible').onchange=function(){state.settings.quotes_invoices_visible=this.checked?1:0;E('portalPreview').innerHTML=portalMenu();icons()};E('requireQuoteSignature').onchange=function(){state.settings.require_quote_signature=this.checked?1:0;E('signaturePreview').innerHTML=signaturePreview();icons()};E('allowQuoteChanges').onchange=function(){state.settings.allow_quote_change_requests=this.checked?1:0;E('changesPreview').innerHTML=changesPreview();icons()};E('showScheduledTime').onchange=function(){state.settings.show_scheduled_time=this.checked?1:0;E('appointmentPreview').innerHTML=appointmentPreview();icons()};E('editReferralMessage').onclick=openReferral;E('copyLoginUrl').onclick=copyUrl;E('updateClientHub').onclick=saveSettings}
function openReferral(){E('referralMessage').value=String(state.settings.referral_message||'{{COMPANY_NAME}} did some great work for me recently. Contact them here if you are interested!');updateCount();E('referralModal').classList.add('open');E('referralModal').setAttribute('aria-hidden','false');icons();setTimeout(function(){E('referralMessage').focus()},30)}
function closeReferral(){E('referralModal').classList.remove('open');E('referralModal').setAttribute('aria-hidden','true')}
function updateCount(){E('referralCount').textContent=String(E('referralMessage').value.length)}
function copyUrl(){var el=E('shareLoginUrl');var value=el.value||'';if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(value).then(function(){toast('success','Customer Hub login URL copied.')}).catch(function(){el.select();document.execCommand('copy');toast('success','Customer Hub login URL copied.')})}else{el.select();document.execCommand('copy');toast('success','Customer Hub login URL copied.')}}
function saveSettings(){var btn=E('updateClientHub'),f=fd('save_settings'),primary=document.querySelector('input[name="primaryAction"]:checked');f.append('quotes_invoices_visible',E('quotesInvoicesVisible').checked?'1':'0');f.append('require_quote_signature',E('requireQuoteSignature').checked?'1':'0');f.append('allow_quote_change_requests',E('allowQuoteChanges').checked?'1':'0');f.append('show_scheduled_time',E('showScheduledTime').checked?'1':'0');f.append('request_form_page_id',E('requestForm').value||'0');f.append('booking_form_page_id',E('bookingForm').value||'0');f.append('primary_action',primary?primary.value:'request');f.append('referrals_enabled',E('referralsEnabled').checked?'1':'0');f.append('referral_message',String(state.settings.referral_message||''));btn.disabled=true;btn.textContent='Saving...';request(f).then(function(d){toast('success',d.message);return load()}).catch(function(e){toast('error',e.message)}).then(function(){btn.disabled=false;btn.textContent='Update Settings'})}
function load(){var f=fd('load');request(f).then(function(d){state.settings=d.settings||{};state.request_forms=d.request_forms||[];state.booking_forms=d.booking_forms||[];state.can_update=d.can_update!==false;render()}).catch(function(e){E('clientHubRoot').innerHTML='<div class="ch-card"><div class="ch-loading">'+esc(e.message)+'</div></div>';toast('error',e.message)})}
E('closeReferralModal').onclick=closeReferral;E('cancelReferralModal').onclick=closeReferral;E('referralModal').onclick=function(e){if(e.target===this)closeReferral()};E('referralMessage').oninput=updateCount;E('saveReferralMessage').onclick=function(){state.settings.referral_message=E('referralMessage').value;closeReferral();toast('success','Referral message updated. Click Update Settings to save all changes.')};document.addEventListener('keydown',function(e){if(e.key==='Escape')closeReferral()});load();icons();
})(window,document);
</script>
